s1 = input("1ª string: ")
s2 = input("2ª string: ")
s3 = ""

for letra in s1:
    if letra not in s2 and letra not in s3:
        s3 += letra

for letra in s2:
    if letra not in s1 and letra not in s3:
        s3 += letra

print(f"Caracteres que aparecem em apenas uma das strings: {s3}")

texto = input("Digite uma string: ")
vistos = []

for c in texto:
    if c not in vistos:
        vistos.append(c)
        print(f"{c}: {texto.count(c)}x")
